with unpivoted as (select * from (select id, customer_id, discount, amount, shipping_fee from orders) src unpivot include nulls (reading for metric in (discount as DISCOUNT_VAL, amount as AMOUNT_VAL, shipping_fee))) select case when reading >= 83 then 'LARGE' else 'SMALL' end as reading_tier, metric, sort_array(collect_set(metric)) as metric_list, sum(case when metric = 'AMOUNT_VAL' then reading else 0 end) as amount_val_reading from unpivoted group by case when reading >= 83 then 'LARGE' else 'SMALL' end, metric order by amount_val_reading desc
